    try {
        popUpCalendar4(edt_SDate, 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar4(edt_EDate, 2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name edt_SDate_OnLastChar
 * @description edt SDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_SDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(1); // if(시작일>종료일) 종료일=시작일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.edt_SDate_OnLastChar" });
    }
};

/**
 * @method
 * @name edt_EDate_OnLastChar
 * @description edt EDate On Last Char 처리
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.edt_EDate_OnLastChar = function(ch) {
    try {
        afterPopUpCalendar(2); // if(시작일>종료일) 시작일=종료일;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.edt_EDate_OnLastChar" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15450.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnFail
 * @description Grid On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnFail = async function() {
    try {
        await scwin.alert_error2(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15450.dts_Grid_OnFail" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await scwin.alert_error2(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15450.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_Grid.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === 'DOC_TITLE') {
            if (scwin.gAcptNo !== '') {
                await $c.stf.openDisclViewer(scwin.gAcptNo, "R", "ULDSTF15450.xml");
            }
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF15450.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF15450.xml", SCREN_PROCS_TP_CD_07, '');
        const file_name = "예약공시 처리현황";
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
        $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        // Grd_com_isur.style.display ="";
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        /*
        if (window.event.keyCode == 40) {
                //아래화살표눌렀을때 그리드로 포커스
        		Grd_com_isur.Focus();
        }else{
        	if (window.event.keyCode ==13){
        		fn_com_Confirm_set();
        	}else{
        		fn_com_isur_nm(window.event.keyCode);
        	}
        }
         */
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF15450.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate);
    edt_EDate.setValue(vCurDate);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    rdo_APPROV_YN.setValue("");
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_Grid.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        for (let j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                if (dtsObj.SrvErrMsg(USER_DEFINE[i], j) === "SESSION_CLOSED") {
                    // 로그아웃
                    $c.frame.path("/top").SystemClose();
                    await $c.win.alert("세션이 종료되었습니다. 다시 로그인해 주세요.");
                } else {
                    await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
                }
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
